package vn.edu.eaut.lab7.model;
public class DiemSinhVien { private int id; private String maSinhVien,hoTen; private double chuyenCan,giuaKy,cuoiKy; public DiemSinhVien(){} public DiemSinhVien(int id,String maSinhVien,String hoTen,double chuyenCan,double giuaKy,double cuoiKy){this.id=id;this.maSinhVien=maSinhVien;this.hoTen=hoTen;this.chuyenCan=chuyenCan;this.giuaKy=giuaKy;this.cuoiKy=cuoiKy;} public double getTongKet(){return chuyenCan*.1+giuaKy*.3+cuoiKy*.6;} public String getXepLoai(){double d=getTongKet();return d>=8.5?"A":d>=7?"B":d>=5.5?"C":d>=4?"D":"F";} public int getId(){return id;} public void setId(int v){id=v;} public String getMaSinhVien(){return maSinhVien;} public void setMaSinhVien(String v){maSinhVien=v;} public String getHoTen(){return hoTen;} public void setHoTen(String v){hoTen=v;} public double getChuyenCan(){return chuyenCan;} public void setChuyenCan(double v){chuyenCan=v;} public double getGiuaKy(){return giuaKy;} public void setGiuaKy(double v){giuaKy=v;} public double getCuoiKy(){return cuoiKy;} public void setCuoiKy(double v){cuoiKy=v;} }